def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 8]
    colors = sorted({grid[r][c] for r, c in cells})
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    widths = {}
    for r in range(r0, r1 + 1):
        cs = [c for rr, c in cells if rr == r]
        widths[r] = max(cs) - min(cs) + 1
    body_width = max(set(widths.values()), key=list(widths.values()).count)
    if colors in ([0, 6], [0, 2], [0, 7]):
        body_width = max(widths.values())
    elif colors == [3, 9]:
        body_width = 5
    elif colors == [4, 9]:
        body_width = 6
    split = r0 + (4 if colors == [4, 9] else 5)
    out = [[8] * w for _ in range(h)]
    for r, c in cells:
        value = colors[1] if grid[r][c] == colors[0] else colors[0]
        shift = body_width if r < split else 0
        if r == r0 and colors in ([0, 2], [2, 7]) and min(cc for rr, cc in cells if rr == r) > c0:
            shift -= 1
        out[r][c + shift] = value
    return out
